const PortColumn = ({ children }) => {
	const { stateContext, setStateContext } = useContext(WebBuilderContext);
	const { setPageData } = useContext(PageDataContext);
	const [expanding, setExpanding] = useState(false);
	const [count, setCount] = useState(0);
	return (
		<div
			onDragEnter={(e) => {
				e.preventDefault();
				setCount((prev) => {
					if (prev === 0) {
						setExpanding(true);
						// console.log('Enter');
					}
					return prev + 1;
				});
			}}
			onDragLeave={(e) => {
				e.preventDefault();
				setCount((prev) => {
					if (prev === 1) {
						setExpanding(false);
						// console.log('Leave');
					}
					return prev - 1;
				});
			}}
			onDrop={(e) => {
				setCount(0);
				setStateContext((prev) => ({
					...prev,
					dropBlock: {
						show: false,
						rect: { left: 0, top: 0, width: 0, height: 0 },
					},
				}));
				const tagId = e.dataTransfer.getData('text');
				setPageData((prev) => {
					const newPD = [...prev];
					/* {
params: {
portId: '2',
cols: 3
},
data: [
{
	params: {
		colId: '0'
	},
	data: [
		{ tag: 'EMImage',  */
					newPD.every((secData) =>
						secData.data.every((colData) =>
							colData.data.every(({ portItemId }, i) => {
								if (portItemId === stateContext.dropingPortItemId) {
									colData.data.splice(i + 1, 0, {
										tag: EMTags[tagId],
										key: colData.data.length + 1,
										portItemId: `${secData.params.portId}-${colData.params.colId}-${colData.data.length}`,
									});
									return false;
								}
								return true;
							})
						)
					);
					return newPD;
				});
			}}
		>
			{children}
			{expanding && stateContext.dropBlock.show && (
				<div className='h-[120px]' />
			)}
		</div>
	);
};
