const MakeEMTag = ({ tag, ...rest }) => {
	switch (tag) {
		case 'EMImage':
			return <EMImage {...rest} />;
		case 'EMImageGroups':
			return <EMImageGroups {...rest} />;
		case 'EMTextHeading':
			return <EMTextHeading {...rest} />;
		case 'EMImageCard':
			return <EMImageCard {...rest} />;
		case 'EMText':
			return <EMText {...rest} />;
		case 'EMBoxedText':
			return <EMBoxedText {...rest} />;
		case 'EMVideo':
			return <EMVideo {...rest} />;
		case 'EMDivider':
			return <EMDivider {...rest} />;
		case 'EMRightText':
			return <EMRightText {...rest} />;
		case 'EMLeftText':
			return <EMLeftText {...rest} />;
		case 'EMBottomText':
			return <EMBottomText {...rest} />;
		case 'EMButton':
			return <EMButton {...rest} />;
		case 'EMSocialFollow':
			return <EMSocialFollow {...rest} />;
		case 'EMSocialShare':
			return <EMSocialShare {...rest} />;
		case 'EMNavigationBar':
			return <EMNavigationBar {...rest} />;
		case 'EMPrmissionReminder':
			return <EMPrmissionReminder {...rest} />;
		case 'EMEcommerce':
			return <EMEcommerce {...rest} />;
		case 'EMEMShopifyImage':
			return <EMShopify {...rest} />;
		case 'EMSavedBlock':
			return <EMSavedBlock {...rest} />;
		default:
			return <EMImage {...rest} />;
	}
};
